                        // session must not block re-delivered messages on the new one.
                        processed_message_ids.clear();
                        debug!("Cleared message dedup set for new session {session_id}");
                    } else {
                        warn!("Session response missing sessionId");
                        consecutive_errors += 1;
                        let delay = retry_backoff.next_delay();
                        tokio::select! {
                            _ = &mut shutdown => return Ok(()),
                            _ = tokio::time::sleep(delay) => {}
                        }
                    }
                }
                Err(e) => {
                    if is_unauthorized(&e) {
                        info!("OAuth token expired during session creation. Re-acquiring token...");
                        match crate::listener::oauth::get_oauth_token(http, &config).await {
                            Ok((new_token, new_expires)) => {
                                token = new_token;
                                token_expires_at = new_expires;
                                consecutive_errors = 0;
                            }
                            Err(oe) => {
                                warn!("Failed to re-acquire OAuth token: {oe:#}");
                                consecutive_errors += 1;
                                let delay = retry_backoff.next_delay();
                                tokio::select! {
                                    _ = &mut shutdown => return Ok(()),
                                    _ = tokio::time::sleep(delay) => {}
                                }
                            }
                        }
                    } else {
                        // Session conflict (409) is retriable with normal backoff
                        // (official TaskAgentSessionConflictException path). #4557
                        // only affects migrated-settings retry caps, which aksh
                        // does not implement.
                        consecutive_errors += 1;
                        let delay = retry_backoff.next_delay();
                        if is_session_conflict(&e) {
                            warn!(
                                "Session conflict (409) creating broker session: {e:#}. Retrying in {delay:?}"
                            );
                        } else {
                            warn!("Failed to create broker session: {e:#}. Retrying in {delay:?}");
                        }
                        tokio::select! {
                            _ = &mut shutdown => return Ok(()),
                            _ = tokio::time::sleep(delay) => {}
                        }
                    }
                    continue;
                }
            }
        }

        let busy = active_job.is_some();
        let kill_at = active_job.as_ref().and_then(|j| j.kill_at);

        tokio::select! {
            _ = &mut shutdown => {
                info!("Shutdown signal received");
                if let Some(mut job) = active_job.take() {
                    shutdown_job_gracefully(http, &mut job).await;
