/// window: the official `Task.WhenAny(firstJobRequestRenewed.Task,
/// renewJobRequest)` cancels the in-flight renew task on the job run token.
async fn first_renew_gate(
    rpt: &ReportingContext,
    mut cancel_rx: watch::Receiver<bool>,
    timing: LeaseTiming,
) -> FirstRenewOutcome {
    const FIRST_RENEW_RETRY_LIMIT: u32 = 5;
    let body = serde_json::json!({ "planId": rpt.plan_id, "jobId": rpt.job_id });
    let mut failures = 0_u32;
    loop {
        if *cancel_rx.borrow() {
            return FirstRenewOutcome::Cancelled;
        }
        let token = rpt.token();
        let renew = rpt.run_service.renew_job(&token, &body);
        tokio::pin!(renew);
        let result = tokio::select! {
            result = &mut renew => result,
            changed = cancel_rx.changed() => {
                if changed.is_err() || *cancel_rx.borrow() {
                    return FirstRenewOutcome::Cancelled;
                }
                // The channel was notified without a real cancellation —
                // restart the renew request (idempotent) rather than
                // blocking on a stalled HTTP call.
                continue;
            }
        };
        match result {
            Ok(_) => return FirstRenewOutcome::Renewed,
            Err(error) if is_job_not_found(&error) => {
                error!("First job renew failed (404) — abandoning job before start");
                return FirstRenewOutcome::Abandoned;
            }
            Err(error) => {
                failures += 1;
                warn!(failures, "first renewjob failed: {error:#}");
                if failures > FIRST_RENEW_RETRY_LIMIT {
                    error!("First job renew retry budget exhausted — abandoning job");
                    return FirstRenewOutcome::Abandoned;
                }
                tokio::select! {
                    _ = tokio::time::sleep(match timing.first_renew_backoff {
                        RenewBackoff::Fixed(delay) => delay,
                        RenewBackoff::Official => {
                            Duration::from_secs(rand::Rng::gen_range(
                                &mut rand::thread_rng(),
                                1..=10,
                            ))
                        }
                    }) => {}
                    changed = cancel_rx.changed() => {
                        if changed.is_err() || *cancel_rx.borrow() {
                            return FirstRenewOutcome::Cancelled;
                        }
                    }
                }
            }
        }
    }
}

/// Build the pause-on-failure client, naming whichever prerequisite is absent.
///
/// Each of these is a distinct operational fault — a server that did not send
/// the run id, a job message without a control endpoint, an unusable
/// transport — and collapsing them into `None` made "pause-on-failure did
/// nothing" impossible to diagnose from the job log.
async fn build_debug_pause_client(
    job_message: &serde_json::Value,
    job_id: &str,
    job_name: &str,
    workspace: &str,
    paused: std::sync::Arc<std::sync::atomic::AtomicBool>,
) -> anyhow::Result<super::debug_pause::DebugPauseClient> {
    let run_id = job_message
        .get("preloopDebugRunId")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("job message carries no preloopDebugRunId"))?
        .parse::<preloop_gha_protocol::RunId>()
        .map_err(|error| anyhow::anyhow!("preloopDebugRunId is not a run id: {error}"))?;
    let agent_job_id = job_id
        .parse::<uuid::Uuid>()
        .map_err(|error| anyhow::anyhow!("job id `{job_id}` is not an agent job GUID: {error}"))?;
    let (service_url, runtime_token) = extract_service_endpoint(job_message)
        .ok_or_else(|| anyhow::anyhow!("job message has no SystemVssConnection endpoint"))?;
    // The debug-worker token is fetched, not read from the job message: the
    // official runner republishes every secret variable as `secrets.*`, so
    // anything delivered that way is readable by the workflow being debugged.
    // The runtime token authenticates the exchange and nothing else — it is
    // scoped to job reporting and revoked at job completion, exactly when a
    // pause still needs to talk to the server, so the credential it buys is
    // minted for that longer window.
    Ok(super::debug_pause::DebugPauseClient::acquire(
        &service_url,
        &runtime_token,
        run_id,
        preloop_gha_protocol::JobId(job_id.to_owned()),
        agent_job_id,
        job_name.to_owned(),
    )
    .await?
    .with_pause_flag(paused)
    .with_pinned_snapshot_steps(
        job_message
            .get("preloopSnapshotTokenSteps")
            .and_then(serde_json::Value::as_array)
            .map(|ids| {
                ids.iter()
                    .filter_map(|id| id.as_str().map(str::to_owned))
                    .collect()
            })
            .unwrap_or_default(),
    )
    .with_workspace(
        Some(workspace.to_owned()),
        job_message
            .get("preloopSnapshotCommit")
            .and_then(|v| v.as_str())
            .map(str::to_owned),
    ))
}

/// Official mid-job renew backoff band: random 5–15 s for the first five
/// consecutive errors, random 15–30 s afterwards
/// (`JobDispatcher.RenewJobRequestAsync`).
fn renew_backoff(encountering_error: u32) -> Duration {
    let (min, max) = if encountering_error > 5 {
        (15, 30)
    } else {
        (5, 15)
    };
    Duration::from_secs(rand::Rng::gen_range(&mut rand::thread_rng(), min..=max))
}

fn parse_lease_deadline(value: &str) -> Option<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(value)
        .ok()
        .map(|deadline| deadline.with_timezone(&Utc))
}

fn lease_expired(locked_until: DateTime<Utc>, now: DateTime<Utc>) -> bool {
    now > locked_until + TimeDelta::minutes(5)
}

